<script setup lang="ts">
import { getBlobBytes } from '@tmt/browser-client'; import { getBlobs } from '@tmt/shared'; import { onBeforeUnmount, ref, watch } from 'vue'; import type { Project } from '../lib/project'
const props = defineProps<{ project: Project; path: string }>(); const url = ref<string | null>(null), error = ref(''), mime = ref('')
watch(() => props.path, async (path) => { if (url.value) URL.revokeObjectURL(url.value); url.value = null; error.value = ''; const info = getBlobs(props.project.doc).get(path); if (!info) return; mime.value = info.mime; if (!/^image\/|^video\//.test(info.mime)) return; try { const bytes = await getBlobBytes(props.project.link, info.hash); url.value = URL.createObjectURL(new Blob([bytes as Uint8Array<ArrayBuffer>], { type: info.mime })) } catch (e) { error.value = e instanceof Error ? e.message : String(e) } }, { immediate: true }); onBeforeUnmount(() => url.value && URL.revokeObjectURL(url.value))
</script><template><div class="flex h-full flex-col items-center justify-center gap-3 overflow-auto p-4"><img v-if="url && mime.startsWith('image/')" :src="url" :alt="path" class="max-h-[70%] max-w-full object-contain" /><video v-else-if="url && mime.startsWith('video/')" :src="url" controls class="max-h-[70%] max-w-full" /><p v-if="error" class="text-error text-sm">{{ error }}</p><p class="text-sm opacity-60">{{ path }} · {{ mime }}</p></div></template>
